#pragma once

// German-only UI strings — this is an internal Product-Manager/Admin tool,
// unlike esp32rental's member-facing terminal, so no runtime EN/DE toggle is
// needed here (see esp32rental/src/i18n.h for that pattern if this ever
// becomes member-facing). Proper umlauts, rendered via the custom
// extended-Latin fonts generated by scripts/gen_fonts.sh (see lv_conf.h) —
// LVGL's built-in fonts only cover 0x20-0x7F, no umlauts at all.

